    #Node Switch
    def switch_false( self, switch: Boolean=None, false: Integer=None):
        """Node Switch.
        
        Jump: False

        **Fixed inputs**

        - self on socket 'True'
        - parameter 'input_type' = 'INT'

        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Integer, optional
            Socket 'False' (default: None)

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {'ID_True': self, 'ID_Switch': switch, 'ID_False': false}

        node = Node( 'Switch', named_sockets=named_sockets, input_type='INT')
        return node._out
